#[path = "<REPOSITORY>/crates/pamin-engine/tests/statistics/mod.rs"]
mod statistics;
use std::collections::BTreeMap;
fn main() {
    let path=std::env::args().nth(1).unwrap();
    let data=std::fs::read_to_string(path).unwrap();
    let mut clusters=BTreeMap::<String,f64>::new();
    let mut count=0;
    let mut sum=0.;
    for line in data.lines() {
        let fields:Vec<_>=line.split('\t').collect();
        assert_eq!(fields.len(),3);
        let before:f64=fields[1].parse().unwrap();
        let after:f64=fields[2].parse().unwrap();
        assert!(before>0. && after>0.);
        let value=(after/before).ln();
        *clusters.entry(fields[0].to_string()).or_default()+=value;
        count+=1;sum+=value;
    }
    assert_eq!(count,1189);
    let values:Vec<_>=clusters.values().copied().collect();
    let result=statistics::compare(&vec![0.;values.len()],&values);
    println!("paired queries {count}; paragraph clusters {}; geometric mean ratio {:.9}; paragraph-cluster sign-flip p {:.6}",values.len(),(sum/count as f64).exp(),result.p);
}
